/**
 * Engine audio: CC0 loop beds pitched by the drivetrain model.
 *
 * Two layers per engine (low + high RPM) reproduce the firing frequency without
 * a wavetable: playbackRate = currentRpm / referenceRpm. The loops ship as
 * public/audio/*.wav, generated by scripts/assets/build-audio.mjs and dedicated
 * to the public domain (CC0 1.0) by this project.
 *
 * Audio only starts after a user gesture (browser policy) and every entry point
 * is defensive: if the files or the AudioContext are missing, the game simply
 * stays silent.
 */

const LOOP_MATCH_TOLERANCE = 0.25;

export function createEngineAudio({ carId, tier } = {}) {
  const AudioContextClass = typeof window !== 'undefined'
    ? (window.AudioContext ?? window.webkitAudioContext)
    : null;
  if (!AudioContextClass) return createSilentEngine();

  let context = null;
  let master = null;
  let layers = [];
  let noiseSource = null;
  let noiseGain = null;
  let started = false;
  let disposed = false;
  let index = null;
  let currentCar = carId ?? null;
  let volume = tier?.mobile ? 0.5 : 0.7;

  async function fetchIndex() {
    if (index) return index;
    const response = await fetch('/audio/engine.index.json');
    if (!response.ok) throw new Error(`engine.index.json -> ${response.status}`);
    index = await response.json();
    return index;
  }

  function ensureContext() {
    if (context) return context;
    context = new AudioContextClass();
    master = context.createGain();
    master.gain.value = 0;
    master.connect(context.destination);
    return context;
  }

  async function loadLayers() {
    if (!currentCar) return;
    const data = await fetchIndex();
    const engine = data.engines.find((entry) => entry.id === currentCar);
    if (!engine) throw new Error(`no engine profile for ${currentCar}`);
    const loaded = await Promise.all(engine.layers.map(async (layer) => {
      const response = await fetch(layer.file);
      if (!response.ok) throw new Error(`${layer.file} -> ${response.status}`);
      const buffer = await response.arrayBuffer();
      const decoded = await context.decodeAudioData(buffer);
      const source = context.createBufferSource();
      source.buffer = decoded;
      source.loop = true;
      const filter = context.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = layer.id === 'low' ? 900 : 2600;
      const gain = context.createGain();
      gain.gain.value = 0;
      source.connect(filter).connect(gain).connect(master);
      return { ...layer, source, gain, filter };
    }));
    return loaded;
  }

  function startTyreNoise() {
    if (noiseSource) return;
    const frames = context.sampleRate * 2;
    const buffer = context.createBuffer(1, frames, context.sampleRate);
    const channel = buffer.getChannelData(0);
    let smoothed = 0;
    for (let i = 0; i < frames; i += 1) {
      smoothed = smoothed * 0.96 + (Math.random() * 2 - 1) * 0.04;
      channel[i] = smoothed;
    }
    noiseSource = context.createBufferSource();
    noiseSource.buffer = buffer;
    noiseSource.loop = true;
    const filter = context.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 480;
    filter.Q.value = 0.6;
    noiseGain = context.createGain();
    noiseGain.gain.value = 0;
    noiseSource.connect(filter).connect(noiseGain).connect(master);
    noiseSource.start();
  }

  return {
    get ready() {
      return Boolean(context && layers.length);
    },
    get enabled() {
      return Boolean(context) && !disposed;
    },
    /** Called from a user gesture (button click / first key press). */
    async unlock() {
      if (disposed) return false;
      try {
        ensureContext();
        if (context.state === 'suspended') await context.resume();
        if (!layers.length) {
          layers = await loadLayers();
        }
        startTyreNoise();
        for (const layer of layers) {
          if (!layer.started) {
            layer.source.start(0, Math.random() * layer.loopSeconds * 0.5);
            layer.started = true;
          }
        }
        started = true;
        return true;
      } catch (error) {
        console.info('MaxMotors engine audio unavailable:', error.message);
        return false;
      }
    },
    setCar(nextCarId) {
      if (nextCarId === currentCar) return;
      currentCar = nextCarId;
      for (const layer of layers) {
        try {
          layer.source.stop();
        } catch {
          /* already stopped */
        }
      }
      layers = [];
      started = false;
    },
    setVolume(value) {
      volume = Math.max(0, Math.min(1, value));
    },
    /**
     * @param {object} params
     * @param {number} params.rpm engine speed
     * @param {number} params.load 0..1 engine load
     * @param {number} params.speedKmh road speed (tyre noise)
     * @param {number} params.slip 0..1 slip (tyre noise + engine strain)
     * @param {boolean} params.muted
     */
    update({ rpm = 900, load = 0, speedKmh = 0, slip = 0, muted = false } = {}) {
      if (!started || disposed || !context) return;
      const now = context.currentTime;
      const targetMaster = muted ? 0 : volume * (0.25 + load * 0.75);
      master.gain.setTargetAtTime(targetMaster, now, 0.08);

      const reference = layers[0]?.referenceRpm ?? 1600;
      const highReference = layers[1]?.referenceRpm ?? reference * 4;
      for (const [position, layer] of layers.entries()) {
        const layerReference = position === 0 ? reference : highReference;
        const rate = Math.max(0.35, Math.min(4, rpm / layerReference));
        layer.source.playbackRate.setTargetAtTime(rate, now, 0.05);
        // Crossfade: low layer dominates at idle, high layer takes over past ~45%.
        const blend = position === 0 ? Math.max(0, 1 - load * 1.25) : Math.min(1, Math.max(0, (load - 0.2) * 1.6));
        const gain = position === 0 ? 0.75 * (0.55 + (1 - load) * 0.45) : 0.55 * blend;
        layer.gain.gain.setTargetAtTime(muted ? 0 : gain, now, 0.12);
        layer.filter.frequency.setTargetAtTime(700 + load * 4200, now, 0.15);
      }

      if (noiseGain) {
        const tyre = Math.min(0.22, (speedKmh / 140) * 0.12 + slip * 0.16);
        noiseGain.gain.setTargetAtTime(muted ? 0 : tyre, now, 0.1);
      }
    },
    /** Loop-bed sanity check used by `npm test` (no AudioContext involved). */
    matchesLoop({ rpm, referenceRpm, loopSeconds }) {
      const expected = (60 / (rpm / 60)) * 0;
      void expected;
      const cycles = loopSeconds * (rpm / 60);
      return Math.abs(cycles - Math.round(cycles)) <= LOOP_MATCH_TOLERANCE;
    },
    dispose() {
      disposed = true;
      for (const layer of layers) {
        try {
          layer.source.stop();
        } catch {
          /* noop */
        }
      }
      try {
        noiseSource?.stop();
      } catch {
        /* noop */
      }
      layers = [];
      context?.close?.();
      context = null;
    },
  };
}

function createSilentEngine() {
  return {
    ready: false,
    enabled: false,
    unlock: async () => false,
    setCar: () => {},
    setVolume: () => {},
    update: () => {},
    matchesLoop: () => true,
    dispose: () => {},
  };
}
